/** The turn's person's own MCP servers (organization mode): the speaker in
 * a conversation, the bot's owner for a routine (the workplace decision's
 * person). A server that still needs a sign-in, a token or GitHub is not
 * mounted; a name Sagax or the server already uses is skipped. */
async function mountPersonalMcp(
  integrations: NonNullable<SendTurnInput["integrations"]>,
  input: { botId: string; threadId: string; generation: string; customMcp: boolean; principal: string | null },
): Promise<void> {
  if (IDENTITY.kind !== "perspicax" || !input.customMcp || !input.principal) return;
  const principalId = input.principal.trim().toLowerCase();
  let servers: Record<string, PersonalMcpServer>;
  try { servers = personConnections.servers(principalId); } catch { return; }
  const github = personGithub(principalId);
  // lot 4: a name the organization declares for this person is theirs
  // (organization > Me); mountPluginMcp mounts it next.
  const orgClaimed = orgCapabilities.claimedNames(principalId);
  for (const [name, server] of Object.entries(servers)) {
    // server/turns/turn-mounts.ts, shared with the capabilities resolver: off, a
    // name the turn already has, a reserved name, no environment for a
    // command, no GitHub connection or token: not mounted
    const check = personalMcpPrecheck(name, server, { taken: (taken) => Object.hasOwn(integrations.custom ?? {}, taken) || orgClaimed.has(taken), hasEnvironment: Boolean(userSandbox), github });
    if ("skip" in check) continue;
    if (check.mount === "stdio") {
      integrations.custom = { ...integrations.custom, [name]: personalStdioIntegration(input.botId, input.threadId, input.generation, principalId, name) };
      continue;
    }
    if (server.kind !== "remote") continue;
    let headers = check.headers;
    // Checked again at each mount (cached): a name that now resolves to a
    // private address is not handed to the engine on this host.
    if (await personalHostRefusalCached(server.url)) continue;
    if (server.auth === "oauth") {
      const manager = personOAuth(principalId);
      const spec = { [name]: personalRemoteSpec(server) };
      await manager.refreshDue(spec).catch(() => undefined);
      const signed = manager.withAuthHeaders(spec)[name]!;
      if (!("url" in signed) || !Object.keys(signed.headers).length) continue;
      headers = signed.headers;
    }
    integrations.custom = { ...integrations.custom, [name]: { type: server.type, url: server.url, headers } };
  }
}

/** A complete plugin's MCP servers use the same selected plugin folders
 * and namespace as the receipt. Commands on an organization server always
 * cross the per-turn relay into this person's environment. */
async function mountPluginMcp(
  integrations: NonNullable<SendTurnInput["integrations"]>,
  input: { botId: string; threadId: string; generation: string; customMcp: boolean; principal: string | null },
): Promise<void> {
  if (!input.customMcp) return;
  const bot = store.bot(input.botId);
  if (!bot) return;
  const person = IDENTITY.kind === "perspicax" ? input.principal?.trim().toLowerCase() : localPrincipalId();
  if (!person) return;
  for (const server of scopedPluginMcp(bot, person)) {
    const refused = pluginMcpPrecheck(server.name, server.spec, {
      taken: (name) => Object.hasOwn(integrations.custom ?? {}, name),
      organization: IDENTITY.kind === "perspicax", hasEnvironment: Boolean(userSandbox)
    });
    if (refused) continue;
    if (!Object.hasOwn(managedPolicy.filterMcp({ [server.name]: server.spec }), server.name)) continue;
    let spec = server.spec;
    if ("url" in spec) {
      if (IDENTITY.kind === "perspicax" && await personalHostRefusalCached(spec.url)) continue;
    } else if (IDENTITY.kind === "perspicax") {
      spec = personalStdioIntegration(input.botId, input.threadId, input.generation, person, server.name, { scope: server.scope, key: server.key, name: server.name });
    } else spec = pluginSpecOnComputer(spec, { name: server.plugin, dir: server.dir });
    integrations.custom = { ...integrations.custom, [server.name]: spec };
  }
}
