/** Stream one already-authorized file with standard single-range semantics.
 * The handle stays the capability: no path is reopened after authorization,
 * and a sealed file decrypts only the chunks intersecting this response. */
function streamOpenedHttpFile(
  req: IncomingMessage,
  res: ServerResponse,
  file: OpenedMessageFile,
  headers: Record<string, string>,
): void {
  // no-transform keeps Caddy's encode, Cloudflare and other proxies from
  // compressing a body whose Content-Length and ranges are stored bytes.
  const cacheControl = headers["cache-control"] ?? "private, no-store";
  const common = {
    ...headers,
    "cache-control": /\bno-transform\b/i.test(cacheControl) ? cacheControl : `${cacheControl}, no-transform`,
    "accept-ranges": "bytes"
  };
  const rawRange = Array.isArray(req.headers.range) ? req.headers.range[0] : req.headers.range;
  const range = parseAttachmentRange(rawRange, file.bytes);
  if (range.kind === "unsatisfiable") {
    void file.handle.close().catch(() => undefined);
    res.writeHead(416, { ...common, "content-range": `bytes */${file.bytes}` });
    res.end();
    return;
  }
  if (res.destroyed) {
    void file.handle.close().catch(() => undefined);
    return;
  }
  const start = range.kind === "range" ? range.start : 0;
  const end = range.kind === "range" ? range.end : file.bytes - 1;
  res.writeHead(range.kind === "range" ? 206 : 200, {
    ...common,
    "content-length": String(Math.max(0, end - start + 1)),
    ...(range.kind === "range" ? { "content-range": `bytes ${start}-${end}/${file.bytes}` } : {})
  });
  if (end < start || res.destroyed) {
    void file.handle.close().catch(() => undefined);
    res.end();
    return;
  }
  const stream = file.stream({ start, end });
  stream.on("error", () => res.destroy());
  res.on("close", () => stream.destroy());
  stream.pipe(res);
}

// Loopback-only enforcement: the harness runs on 127.0.0.1 but accepts
// requests from any loopback connection and any web page that DNS-rebinds
// onto it. Reject non-loopback Hosts outright (defeats rebinding) and
// origins outside loopback (blocks remote-web CSRF).

const workspaceBackupAccess = {
  authorized: (req: IncomingMessage, original: RequestAuth) => {
    const current = resolveRequestAuth(req, {
      sessions, cookieName: SESSION_COOKIE, streamPath: "/api/events",
      url: new URL(req.url ?? "/", `http://localhost:${PORT}`),
      loopbackMutationToken: desktopMutationToken, companionMutationToken, loopbackTrust: LOOPBACK.trust, cliOwnerToken, trustLocalBrowser: LOOPBACK.localBrowsers,
      workerRelayToken: WORKER_RELAY_TOKEN,
      features: { orgDirectory: IDENTITY.kind === "perspicax" },
      permits: sessionPermits
    }).auth;
    // 2026-10-19: a person an admin gave backup.workspace exports, never
    // restores (upload, preview, restore stay an admin's).
    const path = new URL(req.url ?? "/", "http://localhost").pathname;
    const restoring = ["upload", "preview", "restore"].some((step) => path === `/api/workspace-backup/${step}`);
    const delegate = !restoring && current?.kind === "session" && !current.scopes.includes("admin")
      && IDENTITY.kind === "perspicax" && sessionPermits(current.session, "backup.workspace");
    return Boolean(current && (current.scopes.includes("admin") || delegate) && current.kind === original.kind &&
      (current.kind !== "session" || (original.kind === "session" && current.session.id === original.session.id)));
  },
  exclusive: <T>(work: () => Promise<T>, keepLocked?: boolean) => workspaceMaintenance.run(async () => {
    // Recheck inside the exclusive gate: the restore body can arrive slowly
    // while another client assigns a computer after the initial route check.
    if (keepLocked && teamComputers.list().some(computer => computer.section !== null)) {
      throw Object.assign(new Error("Unassign team computers before restoring this workspace"), { status: 409 });
    }
    return work();
  }, {
    idle: () => !providerFleetReloading && !providerAuthSessions.active && !browserEngineInstall &&
      !routines?.isTicking && !calendarCalls?.isTicking &&
      !localVmImageBusy && !localVmProvisionBusy && !localVmModeChangeBusy &&
      !localVmLifecycleBusy.size && !boatLifecycleBusyBots.size && !vpsPreviewRequests.size && !orphanBoatLifecycleBusyIds.size &&
      !computerProviderConfigTransitions.size &&
      teamComputers.list().every(computer => !teamComputerInUse(computer)) &&
      store.bots.every((bot) => !botHasActiveTurn(bot.id) && !routines?.activeRunForBot(bot.id) && !botComputerControlSnapshot(bot.id).held) &&
      store.groups.every((group) => !groupIsWorking(group)),
    pause: () => { botWaits.stop(); routines?.stop(); calendarCalls?.stop(); watchdog.stop(); memoryUpkeep.pause(); },
    resume: () => { routines?.start(); botWaits.start(); calendarCalls?.start(); watchdog.start(); memoryUpkeep.resume(); },
    flush: async () => {
      await Promise.all([flushAllProfileHistory(), flushAllMemoryJournals(), flushUsageLedger(DATA_DIR), flushDecisionLog(DATA_DIR), flushAdminActivity(DATA_DIR)]);
      // With writers gated and work idle, release our WAL connection for the
      // consistent snapshot. Store reopens it lazily after maintenance.
      await closeMessageSearch();
      closeMessageDb();
    }
  }, keepLocked),
  status: () => ({ busy: workspaceMaintenance.active, pendingRestore: workspaceMaintenance.pendingRestore })
};
