/** Bot email keeps the trigger's tool confinement except when the current
 * owner explicitly runs their own configured routine at confirmed Full.
 * The inbound email remains untrusted in either case. */
function botmailConfined(threadId: string): boolean {
  try {
    // 2026-10-30: a proactive wake an email started is confined the same way
    if (activeRoutineRunForThread(threadId)?.proactive?.confined) return true;
    const run = activeRoutineRunForThread(threadId);
    const bot = run ? botForThread(run.botId, threadId) : null;
    const authorizedFull = Boolean(bot && approvalModeFor(bot) === "full" && !orgDeniesFull(bot)
      && supportsApprovalMode(bot.modelSelection, "full") && routineOwnerAuthorizationFor(bot, threadId));
    return botmailRunConfined(run, (id) => webhooks.list().find((hook) => hook.id === id) ?? null, authorizedFull);
  } catch {
    return false;
  }
}
const inboundMail = createBotInboundMailRoute({
  identity: () => IDENTITY.kind,
  publicOrigin: () => (IDENTITY.kind === "perspicax" ? IDENTITY.publicOrigin.replace(/\/+$/, "") : null),
  linkServerId: () => perspicaxDirectory?.serverId() ?? null,
  verify: (token, audience, serverId) => {
    if (!oidcRp) throw new Error("This server has no identity provider configured.");
    return oidcRp.verifyConsoleAssertion(token, audience, serverId, BOT_MAIL_ASSERTION_ACTORS);
  },
  bot: (id) => {
    const bot = store.bot(id);
    return bot ? { id: bot.id, name: bot.name } : null;
  },
  owner: (id) => botMailOwner(id),
  triggers: (botId) => webhooks.list().filter((hook) => hook.enabled && hook.botId === botId && hook.source?.type === "botmail").map((hook) => hook.id),
  ingest: (id, event, key) => webhooks.ingest(id, event, key),
  // Plus-tag routing: name+tag@ wakes only the routine(s)
  // of this bot with that mailAlias. Untagged mail keeps botmail triggers.
  routines: (botId) => (routines?.listRoutines() ?? [])
    .filter((routine) => routine.botId === botId)
    .map((routine) => ({
      id: routine.id,
      botId: routine.botId,
      name: routine.name,
      enabled: routine.enabled,
      suspended: Boolean(routine.suspended),
      ...(routine.mailAlias ? { mailAlias: routine.mailAlias } : {})
    })),
  wakeRoutine: (routineId, event, dedupeKey) => {
    const routine = routines?.listRoutines().find((candidate) => candidate.id === routineId);
    if (!routine || !routine.enabled || routine.suspended) return null;
    const now = Date.now();
    // Synthetic webhook id: missing from the trigger list, so S2 confinement
    // treats the run as a mail-woken one (botmailRunConfined fail-closed).
    const webhookId = `mail-tag:${routine.id}`;
    const prior = routines!.webhookRunReceipt(webhookId, dedupeKey);
    const run = routines!.enqueueWebhook({
      webhookId,
      webhookName: routine.name,
      prompt: botmailTaggedPrompt(routine.prompt, event, now, dedupeKey),
      botId: routine.botId,
      runOn: routine.runOn,
      deliveryId: dedupeKey,
      receivedAt: now,
      routineId: routine.id
    });
    return { runId: run.id, deliveryId: dedupeKey, duplicate: Boolean(prior) };
  },
  // 2026-10-30: an email no routine took wakes the bot (its proactive
  // mode), confined like a mail-woken run
  unhandled: (botId, mail) => {
    const event = botmailEvent(mail);
    const domain = senderDomain(mail.from.address);
    offerProactive({
      botId, source: "mail", key: `mail:${mail.dedupeKey}`, confined: true,
      label: `Email from ${domain || "an unknown domain"}`,
      summary: `${mail.from.address}: ${mail.subject.trim() || "(no subject)"}`,
      detail: `Subject: ${mail.subject.trim() || "(no subject)"}\n${event.text ?? ""}`,
      hops: 0
    });
  },
  record: (row) => appendAdminAction(DATA_DIR, {
    category: "webhook",
    action: "bot-mail.delivered",
    target: { kind: "bot", id: row.botId, name: row.botName },
    after: { triggers: row.triggers, delivered: row.delivered, duplicate: row.duplicate, ignored: row.ignored, sender: row.sender },
    actor: { kind: "person", principalId: row.ownerPrincipalId, via: "perspicax-mail" }
  })
});
// 2026-10-26 (Perspicax Voice, phase 2): a text or a call on the owner's
// phone line wakes the chosen bot's Bot phone triggers
