function saveOrgPluginMarketplaces(raw: unknown, actor: AdminActor): void {
  // lot 4: one owner. On a server whose Perspicax owns the rule, this local
  // copy is never a second store: write it in Perspicax (or through
  // Sources > Organization, which writes there).
  if (orgCapabilitiesOwner() === "perspicax") throw new OrgSettingOwnedElsewhere();
  const parsed = marketplacePolicySchema.safeParse(raw);
  if (!parsed.success) throw new Error("Send { mode: \"any\" } or { mode: \"list\", allow: [\"owner/repo\", \"owner/*\", \"https://...\"] }.");
  const next: MarketplacePolicy = parsed.data.mode === "any" ? { mode: "any" } : { mode: "list", allow: [...new Set(parsed.data.allow.map(normalizePolicyEntry))] };
  const before = historicalPluginMarketplacePolicy() ?? { mode: "any" };
  saveConfig({ organization: { ...cfg.organization, pluginMarketplaces: next } });
  cfg.organization = { ...cfg.organization, pluginMarketplaces: next };
  orgAudit({
    category: "org", action: "org.settings", target: { kind: "organization" }, changed: ["pluginMarketplaces"],
    before: { pluginMarketplaces: before }, after: { pluginMarketplaces: next }, actor
  });
}

/** The organization's engine policy (Settings, Policies): every engine
 * until a list is set. */
function consoleEngineAllowed(instanceId: string): boolean {
  return engineAllowed(orgAllowedEngines(), instanceId);
}
/** 2026-10-30 (lot 2): the models the organization turned off in Perspicax
 * (`<engine>/<model>`, shared/offered-models.ts). Empty on a solo server. */
function orgDisabledModels(): string[] {
  return IDENTITY.kind === "perspicax" ? cleanDisabledModels(cfg.organization?.disabledModels) : [];
}
/** The models this person turned off (an organization server's person), or
 * the installation's own list on a solo server. */
function personDisabledModels(principalId: string | null | undefined): string[] {
  if (IDENTITY.kind !== "perspicax") return cleanDisabledModels(cfg.disabledModels);
  const owner = personSettingsOwner(principalId);
  return owner ? personSettings.get(owner).disabledModels ?? [] : [];
}
/** Both levels for one person (a bot's owner, a turn's payer). */
function modelSwitchesFor(principalId: string | null | undefined): ModelSwitches {
  return { org: orgDisabledModels(), mine: personDisabledModels(principalId) };
}
/** Why this model may not be picked or run for this person, if it may not. */
function modelSwitchRefusal(instanceId: string, model: string, principalId: string | null | undefined): string | undefined {
  const offer = modelOffer(modelSwitchesFor(principalId), instanceId, model);
  if (offer === "adminOff") return MODEL_TURNED_OFF_BY_ORG;
  if (offer === "personOff") return MODEL_TURNED_OFF_BY_PERSON;
  return undefined;
}
/** A bot on a model now off (the organization's switch, or its owner's own)
 * moves to Auto on the same engine, from its first model still on; a
 * thread's own model follows its bot. `owner`: only that person's bots. */
function applyModelSwitches(owner?: string): void {
  for (const { id } of store.bots) {
    const bot = store.bot(id);
    if (!bot) continue;
    const botOwner = effectiveBotOwner(bot);
    if (owner !== undefined && botOwner !== owner) continue;
    const switches = modelSwitchesFor(botOwner);
    const selection = bot.modelSelection;
    const withoutDisabledFast = (value: ModelSelection): ModelSelection => {
      if (!value.fast || modelOn(switches, value.fast.instanceId, value.fast.model)) return value;
      const { fast: _fast, ...rest } = value;
      return rest;
    };
    const cleaned = withoutDisabledFast(selection);
    if (cleaned !== selection) store.applyModelDefault(id, cleaned);
    const offer = modelOffer(switches, selection.instanceId, selection.model);
    if (offer !== "on") {
      const live = registry.get(selection.instanceId);
      const next = live?.models.options.find((option) => !option.custom && modelOn(switches, selection.instanceId, option.id));
      // Auto can use another ready engine even when this engine has no
      // model left on. Its concrete selection is checked before dispatch.
      const model = next?.id ?? selection.model;
      store.applyModelDefault(id, { instanceId: selection.instanceId, model, auto: true });
      console.log(`[models] bot=${id} model ${selection.instanceId}/${selection.model} is turned off; now on Auto (${model})`);
      if (offer === "adminOff" && bot.threadId) {
        const move = { from: selection.model, to: orgEngineName(selection.instanceId) };
        store.appendMessage(bot.threadId, { role: "bot", kind: "activity", tool: { name: `notice: ${orgEngineMoveLine(move)}`, ok: true, engineMove: move } });
      }
    }
    for (const task of store.bot(id)?.tasks ?? []) {
      if (!task.modelSelection) continue;
      const cleanedTask = withoutDisabledFast(task.modelSelection);
      if (cleanedTask !== task.modelSelection) store.patchTask(id, task.threadId, { modelSelection: cleanedTask });
    }
    const stray = (store.bot(id)?.tasks ?? [])
      .filter((task) => task.modelSelection && !modelOn(switches, task.modelSelection.instanceId, task.modelSelection.model))
      .map((task) => task.threadId);
    if (stray.length) store.followBotModel(id, stray, (from, to) => hostedModels?.resetTask(from, to) ?? {});
  }
}
/** 2026-10-30: the organization lets a person run an engine outside its
 * list on their own subscription or key (Perspicax, Model providers:
 * `ownAccountsOutsideList`). Off by default: what the admin turns off is
 * off for everyone, the admin included. Solo: never asked. */
function orgOwnAccountsOutsideList(): boolean {
  return IDENTITY.kind === "perspicax" && cfg.organization?.ownAccountsOutsideList === true;
}
/** Organization server: the engines its admin allows (Perspicax), null for
 * every engine (shared/org-allowed-engines.ts). */
function orgAllowedEngines(): string[] | null {
  const allowed = cfg.organization?.allowedEngines;
  // [] is "none" (2026-10-17): only null or absent means every engine
  return IDENTITY.kind === "perspicax" && Array.isArray(allowed) ? allowed : null;
}
/** Why a model choice may not use this engine here, if it may not.
 * 2026-10-30: an engine outside the organization's list is refused to
 * everyone, admins included. Only with `ownAccountsOutsideList` does it stay
 * open to a person (`payer`) who pays for it with their own subscription or
 * key (#1098). */
function orgEngineAllowRefusal(instanceId: string, payer?: string | null): string | undefined {
  if (consoleEngineAllowed(instanceId)) return undefined;
  return orgOwnAccountsOutsideList() && payer && personPaysEngine(payer, instanceId) ? undefined : ORG_ENGINE_NOT_ALLOWED;
}
/** The organization's engine list for one turn: an engine outside it never
 * runs (2026-10-30), unless the organization lets own accounts through and
 * the turn's payer pays with their own subscription or key (#1098). */
function orgEngineTurnRefusal(bot: BotRecord, instance: { instanceId: string; driverKind: string }, speaker: TurnSpeaker): string | undefined {
  if (consoleEngineAllowed(instance.instanceId)) return undefined;
  if (!orgOwnAccountsOutsideList()) return ORG_ENGINE_NOT_ALLOWED;
  // #1422: a local pi model gets no exemption here. On an organization server
  // its local host (127.0.0.1, server/drivers/local-inject.ts) is the
  // server's own machine, shared by every member, not the person's: the
  // organization's engine list decides for it as for any engine it runs.
  // Without a list (the default) every engine is allowed, pi included. A
  // model on the person's own computer is a desktop model (desktop-inject),
  // which this list never gated.
  return paidByPerson(resolveEngineAccess(orgEngineInput(bot, instance, speaker))) ? undefined : ORG_ENGINE_NOT_ALLOWED;
}
/** #1098: this person's own subscription or key would pay for their turn
 * on this engine (engine-credentials.ts steps 3 and 4). */
function personPaysEngine(principalId: string, instanceId: string): boolean {
  if (IDENTITY.kind !== "perspicax") return false;
  const id = principalId.trim().toLowerCase();
  if (!id || !isPrincipalId(id)) return false;
  const entry = registry.entries().find((candidate) => candidate.instanceId === instanceId);
  const driverKind = entry?.shadow?.driverKind ?? entry?.live?.driverKind ?? "";
  if (!driverKind) return false;
  const person = principals.byId(id);
  return paidByPerson(resolveEngineAccess({
    identity: IDENTITY.kind,
    speaker: { origin: "person", principalId: id },
    owner: { principalId: id, ...orgPersonFacts(person) },
    instance: { instanceId, driver: driverKind, installed: engineInstalled(instanceId),
      ...(personalProviderInstances.get(instanceId) ? { keyOnly: true, keyProvider: personalProviderInstances.get(instanceId)!.provider, personalOwner: personalProviderInstances.get(instanceId)!.owner } : {}) },
    subscriptionSignedIn: (pid, driver) => engineLogins?.signedIn(pid, driver) ?? false,
    subscriptionExpired: (pid, driver) => engineLogins?.expired(pid, driver) ?? false,
    hasKey: (sub, provider) => perspicaxDirectory?.providerKeys(sub).includes(provider) ?? false,
    keyBacked: false,
    hasLocalKey: (pid, driver) => fileKeyConfigured(DATA_DIR, { organization: true, principalId: pid }, driver)
  }));
}
/** The engines as the console's Model providers card lists them (GET
 * capabilities, api 4): the same access groups as the model picker's
 * provider column (src/lib/engine-rail.ts splitEngineRail: a custom engine
 * is Local, an API key or a subscription engine is Cloud). */
function orgAdminEngines(): AdminEngine[] {
  const configs = providerConfigs();
  const engines: AdminEngine[] = registry.entries().filter((entry) => !personalProviderInstances.get(entry.instanceId)).map((entry) => {
    const live = registry.get(entry.instanceId);
    const access = configs[entry.instanceId]?.access ?? registry.access(entry.instanceId);
    const auth: AdminEngine["auth"] = access === "api" ? "apiKey"
      : access === "custom" ? "none"
      : live?.startAuthentication ? "oauth" : "none";
    const driver = entry.shadow?.driverKind ?? entry.live?.driverKind ?? "";
    return {
      id: entry.instanceId,
      name: live ? engineDisplayName(live) : entry.instanceId,
      kind: access === "custom" ? "local" : "cloud",
      installed: engineInstalled(entry.instanceId),
      auth,
      // 2026-10-16: the organization's key serves this engine (never the
      // key): the engines a person sheet's sagax_server_engines can give.
      orgKey: driverKeyBacked(cfg, driver, entry.instanceId)
    };
  });
  // Voice mode on the organization's xAI key is given the same way.
  if (cfg.xai?.key) engines.push({ id: VOICE_SERVER_ENGINE, name: "Grok voice (xAI)", kind: "cloud", installed: true, auth: "apiKey", orgKey: true, voice: true });
  if (voiceCredential(cfg.tts?.key)) engines.push({ id: ELEVENLABS_VOICE_SERVER_ENGINE, name: "ElevenLabs voice", kind: "cloud", installed: true, auth: "apiKey", orgKey: true, voice: true });
  if (cfg.tts?.fishKey) engines.push({ id: FISH_VOICE_SERVER_ENGINE, name: "Fish Audio voice", kind: "cloud", installed: true, auth: "apiKey", orgKey: true, voice: true });
  // 2026-10-16: Grok voice also covers read aloud and voice notes when the
  // voice engine is xAI; avatar images on the organization's xAI key are
  // given the same way.
  if (cfg.xai?.key) engines.push({ id: IMAGE_SERVER_ENGINE, name: "Grok images and videos (xAI)", kind: "cloud", installed: true, auth: "apiKey", orgKey: true, image: true });
  return engines;
}
/** An engine's name for a person (its id when the registry no longer has it). */
function orgEngineName(instanceId: string): string {
  const live = registry.get(instanceId);
  return live ? engineDisplayName(live) : instanceId;
}
/** A bot whose engine left the organization's list falls back to Auto on an
 * allowed engine (the New bot default when allowed, else the first allowed
 * engine here), and a thread's own model on such an engine follows its bot
 * again. At start and whenever the list changes. */
function applyOrgEngineAllowList(): void {
  const allowed = orgAllowedEngines();
  if (!allowed) return;
  const engines = registry.entries().map((entry) => ({
    instanceId: entry.instanceId,
    installed: engineInstalled(entry.instanceId),
    defaultModel: registry.get(entry.instanceId)?.models.default ?? ""
  }));
  const preferred = cfg.newBotDefaults?.profile.modelSelection ?? cfg.defaultModelSelection;
  for (const { id } of store.bots) {
    const bot = store.bot(id);
    if (!bot) continue;
    // #1098: an engine its owner pays for with their own subscription or
    // key is theirs to keep, only when the organization lets own accounts
    // through (2026-10-30, `ownAccountsOutsideList`)
    const owner = effectiveBotOwner(bot);
    const ownKept = (instanceId: string) => orgOwnAccountsOutsideList() && personPaysEngine(owner, instanceId);
    const next = ownKept(bot.modelSelection.instanceId) ? null : allowedFallbackSelection(bot.modelSelection, allowed, engines, preferred);
    if (next) {
      store.applyModelDefault(id, next);
      console.log(`[org] bot=${id} engine ${bot.modelSelection.instanceId} is not allowed by the organization; now on Auto (${next.instanceId})`);
      // 2026-10-18 the bot's conversation says so in one plain line
      // (a status notice, drawn in the reader's language from tool.engineMove,
      // src/lib/activity-runs.ts), never a raw error.
      const move = { from: orgEngineName(bot.modelSelection.instanceId), to: orgEngineName(next.instanceId) };
      if (bot.threadId) store.appendMessage(bot.threadId, { role: "bot", kind: "activity", tool: { name: `notice: ${orgEngineMoveLine(move)}`, ok: true, engineMove: move } });
    }
    const stray = (store.bot(id)?.tasks ?? [])
      .filter((task) => task.modelSelection && !engineAllowed(allowed, task.modelSelection.instanceId) && !ownKept(task.modelSelection.instanceId))
      .map((task) => task.threadId);
    if (stray.length) store.followBotModel(id, stray, (from, to) => hostedModels?.resetTask(from, to) ?? {});
  }
}

/** What a manager's reach is checked against for one bot (the bots route
 * and the files routes of the console's admin API). */
function orgBotReach(bot: BotRecord): AdminBotReach {
  const facts = botFacts(bot);
  const sectionName = sectionKey(bot.section);
  const record = sectionName && sectionChannels ? sectionChannels.byName(sectionName) : undefined;
  const shared = record && facts.sections?.length ? record : undefined;
  return {
    ownerPrincipalId: facts.ownerPrincipalId,
    grantTargets: facts.grants.map((grant) => grant.target),
    sectionMemberTargets: shared ? shared.members.map((member) => member.target) : []
  };
}

/** A path inside this server's data folder (real paths), for the project
 * folder root of the console's file browser: a working folder elsewhere on
 * the host is never browsed from Perspicax. */
function insideDataDir(path: string): boolean {
  try {
    const root = realpathSync(DATA_DIR);
    const real = realpathSync(path);
    return real === root || real.startsWith(root.endsWith(sep) ? root : root + sep);
  } catch {
    return false;
  }
}

/** The roots of a bot's files for the console's file browser
 * (server/org/org-admin-files.ts); never a path on the wire. */
function orgBotFileRoots(bot: BotRecord): BotFileRoot[] {
  // A confidential thread's folder is never in the console (server/threads/confidential-threads.ts).
  const confidential = new Set(store.tasks(bot.id).filter((task) => task.confidential === true).map((task) => task.threadId));
  const folder = (id: "workspace" | "tasks", dir: string): BotFileRoot => existsSync(dir)
    ? { id, kind: "folder", dir, ...(id === "tasks" && confidential.size ? { hidden: confidential } : {}) }
    : { id, kind: "unavailable", reason: "not_created" };
  const project: BotFileRoot = !bot.cwd
    ? { id: "project", kind: "unavailable", reason: "not_set" }
    : !existsSync(bot.cwd)
      ? { id: "project", kind: "unavailable", reason: "not_created" }
      : insideDataDir(bot.cwd) ? { id: "project", kind: "folder", dir: bot.cwd } : { id: "project", kind: "unavailable", reason: "outside_server_data" };
  return [
    folder("workspace", workspaceDir(bot.id)),
    folder("tasks", join(TASK_WORKSPACES_DIR, bot.id)),
    project,
    { id: "attachments", kind: "attachments", dir: ATTACHMENTS_DIR },
    { id: "sandbox", kind: "unavailable", reason: "person_environment" },
    { id: "desktop", kind: "unavailable", reason: "own_computer" },
  ];
}

/** The uploads and attach_file outputs of every conversation of a bot. */
async function orgBotAttachments(bot: BotRecord): Promise<BotAttachment[]> {
  // A confidential thread's uploads and outputs are never listed, and a file
  // it shares with an ordinary thread is left out too.
  const confidential = new Set(store.tasks(bot.id).filter((task) => task.confidential === true).map((task) => task.threadId));
  const threads = [...new Set([bot.threadId, ...store.tasks(bot.id).map((task) => task.threadId)])].filter((threadId) => !confidential.has(threadId));
  const confidentialFiles = new Set<string>();
  for (const threadId of confidential) {
    for (const ref of threadFileRefs(store.messagesFor(threadId), bot.id)) if (ref.source === "upload" || ref.source === "attachment") confidentialFiles.add(ref.path);
  }
  const out: BotAttachment[] = [];
  for (const threadId of threads) {
    const refs = threadFileRefsFor(threadId).filter((ref) => (ref.source === "upload" || ref.source === "attachment") && !confidentialFiles.has(ref.path));
    if (!refs.length) continue;
    const files = await listThreadFiles(refs, (ref) => statMessageFile(ref.path, threadFileRoots(threadId, ref))).catch(() => []);
    for (const file of files) {
      if (file.available && file.localPath) out.push({ id: file.id, name: file.name, at: file.at, localPath: file.localPath });
    }
  }
  return out;
}

