ROUTES.push(createLocalComputerRoutes({
  interruptLocalComputerBots: async () => {
    await Promise.allSettled(
      store.bots
        .filter((bot) => bot.computer === "local")
        .map(async (bot) => {
          await interruptAllDirectThreads(bot.id);
          const routineRun = routines!.activeBotRunForBot(bot.id);
          if (routineRun) {
            cancelDirectTurnDispatch(bot.id, routineRun.threadId);
            if (routineRun.threadId) {
              revokeInternalCapabilitiesForThread(routineRun.threadId);
            }
            await routines!.cancelRun(routineRun.id);
          }
          const groupTurn = activeGroupTurnForBot(bot.id);
          if (groupTurn) {
            cancelGroupTurnOperations(groupTurn.group.id, groupTurn.threadId);
            revokeInternalCapabilitiesForThread(groupTurn.threadId);
            await runningTurnInstance(bot, groupTurn.threadId)?.adapter.interruptTurn(groupTurn.threadId).catch(() => {});
            closeOpenApprovals(groupTurn.threadId);
          }
        }),
    );
  },
  sharedPayload: (auth) => localVmPayload(SHARED_LOCAL_VM_TARGET, auth),
  inventoryPayload: () => localVmInventoryPayload(),
  hostRefusal: hostComputerRefusal,
  setupBusy: () => localVmImageBusy || localVmModeChangeBusy || localVmLifecycleBusy.has(SHARED_LOCAL_VM_TARGET.key),
  sharedInUse: () => localVmLeaseFor(SHARED_LOCAL_VM_TARGET).current(localVmOwnerBusy) !== null,
  sharedActiveThread: () => localVmActiveThreads.has(SHARED_LOCAL_VM_TARGET.key),
  sharedLifecycleBusy: () => localVmLifecycleBusy.has(SHARED_LOCAL_VM_TARGET.key),
  mode: () => localVmMode(cfg),
  maxInstances: () => localVmMaxInstances(cfg),
  idleTimeoutMs: localVmIdleMs,
  runSharedAction: async (action, auth) => {
    if (action === "pull") localVmImageBusy = true;
    else localVmLifecycleBusy.add(SHARED_LOCAL_VM_TARGET.key);
    try {
      const status = await containerComputerAction(action, undefined, undefined, SHARED_LOCAL_VM_TARGET);
      if (action === "run" || action === "start") {
        localVmSeen.add(SHARED_LOCAL_VM_TARGET.key);
      }
      return {
        ...localVmViewerStatus(status, auth),
        commands: setupCommands(status.runtime, process.platform, SHARED_LOCAL_VM_TARGET)
      };
    } finally {
      if (action === "pull") localVmImageBusy = false;
      else localVmLifecycleBusy.delete(SHARED_LOCAL_VM_TARGET.key);
    }
  },
  sharedScreenshot: () => containerComputerScreenshot(undefined, undefined, SHARED_LOCAL_VM_TARGET),
  touchSharedIdle: () => localVmIdleFor(SHARED_LOCAL_VM_TARGET).touch(),
  cancelSharedIdle: () => localVmIdleFor(SHARED_LOCAL_VM_TARGET).cancel(),
  personStarted: () => { localVmAuto?.personStarted(); },
  personStopped: () => { localVmAuto?.personStopped(); },
  previewBot: computerPreviewBot,
  botPayload: (bot, auth) => localVmPayload(localVmTargetForStatus(bot.id, bot.threadId), auth),
  bot: (id) => store.bot(id) ?? null,
  boatLifecycleBusy: (botId) => boatLifecycleBusyBots.has(botId),
  botTargetShared: (botId) => localVmTargetForBot(botId).key === SHARED_LOCAL_VM_TARGET.key,
  botSetupBusy: (botId) => {
    const target = localVmTargetForBot(botId);
    return localVmImageBusy || localVmModeChangeBusy || localVmLifecycleBusy.has(target.key);
  },
  botProvisionBusy: () => localVmProvisionBusy,
  botInUse: (botId) => localVmLeaseFor(localVmTargetForBot(botId)).current(localVmOwnerBusy) !== null,
  botActiveThread: (botId) => localVmActiveThreads.has(localVmTargetForBot(botId).key),
  botLifecycleBusy: (botId) => localVmLifecycleBusy.has(localVmTargetForBot(botId).key),
  runBotAction: async (botId, action, auth) => {
    const target = localVmTargetForBot(botId);
    localVmLifecycleBusy.add(target.key);
    if (action === "run") localVmProvisionBusy = true;
    try {
      if (action === "run") {
        const before = await containerComputerStatus(undefined, undefined, target);
        if (!before.runtime) {
          return {
            ...localVmViewerStatus(before, auth),
            commands: setupCommands(before.runtime, process.platform, target),
            noRuntime: true,
            problem: before.problem ?? undefined
          };
        }
        if (!(await containerComputerExists(before.runtime, target))) {
          const count = await existingPerBotLocalVmCount(before.runtime);
          if (count >= localVmMaxInstances(cfg)) {
            return {
              overCap: true,
              cap: localVmMaxInstances(cfg),
              commands: setupCommands(before.runtime, process.platform, target)
            };
          }
        }
      }
      const status = await containerComputerAction(action, undefined, undefined, target);
      if (action === "run" || action === "start") {
        localVmSeen.add(target.key);
      }
      return {
        ...localVmViewerStatus(status, auth),
        commands: setupCommands(status.runtime, process.platform, target)
      };
    } finally {
      if (action === "run") localVmProvisionBusy = false;
      localVmLifecycleBusy.delete(target.key);
    }
  },
  botScreenshot: (bot, threadId) => containerComputerScreenshot(undefined, undefined, localVmTargetForStatus(bot.id, threadId)),
  touchBotIdle: (botId, threadId) => localVmIdleFor(localVmTargetForStatus(botId, threadId)).touch(),
  cancelBotIdle: (botId) => localVmIdleFor(localVmTargetForBot(botId)).cancel(),
  previewSurface: computerPreviewSurface,
  controlLeaseOk: (botId, leaseId) => {
    const controlBot = store.bot(botId);
    return Boolean(controlBot && computerControl.ownsLease(botComputerControlKey(controlBot), leaseId));
  },
  botJoinStatus: (botId, threadId) => containerComputerStatus(undefined, undefined, localVmTargetForStatus(botId, threadId)),
  viewerSocketPath: (botId, threadId, leaseId) => {
    const target = localVmTargetForStatus(botId, threadId);
    const socket = new URLSearchParams({ botId, ...(threadId ? { threadId } : {}), controlLeaseId: leaseId });
    return `api/desktop-viewer/${viewerTargetId(target)}/websockify?${socket}`;
  }
}));
