const handleRequest = async (req: IncomingMessage, res: ServerResponse) => {
  const parsed = parseRequest(req, res, PORT, json);
  if (!parsed) return;
  const { url, path, method } = parsed;
  /** Shared scratch for named handleRequest steps (#1388 wave 4 step 2). */
  const state: { m: RegExpMatchArray | null; releaseWorkspaceRequest?: () => void; scopes?: RequestScopes } = { m: null };
  try {
    if (await originGates(req, res, url, path, method)) return;
    if (await runPreAuth(req, res, url, path, method)) return;
    const auth = await authenticate(req, res, url, path, method, state);
    if (!auth) return;
    // Set for every request, so a kept-alive connection never inherits one.
    enterRequestScopes(state.scopes ?? { viewer: null, delegated: false, continuation: null, actConfirmed: null });
    if (await runRoutes(req, res, url, path, method, auth)) return;
    if (await runInternal(req, res, url, path, method, auth)) return;
    if (await fallback(req, res, url, path, method, auth, state)) return;
  } catch (e) {
    const status = (e as any)?.status ?? 500;
    const candidateCode = (e as { code?: unknown })?.code;
    const code = typeof candidateCode === "string" && ["guarded_busy", "guarded_branch", "guarded_permissions", "guarded_request_changed", "guarded_request_untracked", "outside_workspace", "org_full_access_disabled", "parallel_limit", "parallel_nested", "misuse_blocked", "misuse_approval_required", "misuse_locked", "safety_blocked", "no_engine"].includes(candidateCode)
      ? candidateCode : undefined;
    // 2026-11-02: a misuse block names its one reason (a category id)
    const candidateReason = (e as { reason?: unknown })?.reason;
    const reason = code === "misuse_blocked" && typeof candidateReason === "string" && /^[a-z_]{1,40}$/.test(candidateReason) ? candidateReason : undefined;
    return json(res, status, { error: e instanceof Error ? e.message : String(e), ...(code ? { code } : {}), ...(reason ? { reason } : {}) });
  } finally {
    state.releaseWorkspaceRequest?.();
  }
};

// The packaged desktop opened the port before this module loaded and has
// answered the page from it meanwhile (server/early-listener.ts): take it over.
const earlyListener = (globalThis as { __sagaxEarlyListener?: EarlyListener | null }).__sagaxEarlyListener ?? null;
const server = earlyListener?.server ?? createServer(handleRequest);
desktopViewer.attach(server, handleRequest);
/** The desktop bridge's network tunnel (organization mode): the WebSocket a
 * person's desktop app opens, checked against their live session and the
 * desktop's own secret before any byte is relayed. */
const desktopTunnelDeps = {
  organization: () => IDENTITY.kind === "perspicax",
  session: (req: IncomingMessage) => {
    const token = parseCookies(req.headers.cookie).get(SESSION_COOKIE);
    const found = token ? sessions.authenticate(token) : null;
    const record = found && !sessions.needsRecheck(found.id) ? found : null;
    const person = record ? liveSessionPerson(record.id) : null;
    return record && person ? { id: record.id, person } : null;
  },
  sameOrigin: (req: IncomingMessage) => isSameOrigin(req),
  bridgeOwner: (id: string, session: string, secret: string) => desktopBridges.owns(id, session, secret),
  tunnels: desktopTunnels
};
attachDesktopTunnel(server, desktopTunnelDeps);
attachDesktopTerminal(server, { ...desktopTunnelDeps, terminals: desktopTerminals });
if (IDENTITY.kind === "perspicax") {
  egressProxy = await startEgressProxy({
    tunnels: desktopTunnels,
    audit: (entry) => bridgeAudit.record({
      person: entry.person, botId: entry.botId, threadId: entry.threadId, target: entry.via === "desktop" ? "user-desktop" : "direct",
      kind: "network", detail: `${entry.host}:${entry.port}`, ok: entry.ok, error: entry.error
    })
  });
  try {
    await desktopLocalModels.listen();
  } catch (error) {
    console.error(`[desktop-local-models] proxy did not start: ${error instanceof Error ? error.message : "unavailable"}`);
  }
}

calendarCalls.start();

// Resolve the edition before accepting requests so /api/edition is never a guess.
console.log(describeEdition(await loadEnterpriseLayer()));
// A key inside its last 30 days, or already in its grace period, says so
// where an operator reads first.
const startupLicenseWarning = licenseWarning(editionStatus());
if (startupLicenseWarning) console.warn(startupLicenseWarning);
console.log(LOOPBACK.trust === "service"
  ? `local requests: service trust (${LOOPBACK.reason}); without a session, loopback may use only health, edition, brand and bot capability routes. ${WORKER_RELAY_TOKEN ? "The worker data plane answers only when the relay token is presented." : "The worker data plane stays closed until a relay token is configured."}`
  : `local requests: owner trust (${LOOPBACK.reason})`);
if (LOOPBACK.warning) console.warn(`local requests: ${LOOPBACK.warning}`);
// The decision log also prunes as it writes; this covers a quiet server.
// Every room's floor, once, before any request: a room that was already
// mixed when this server started keeps its narrowest audience from here on.
for (const group of store.groups) settleRoomFloor(group);
const pruneDecisionLog = () => {
  void pruneDecisions(DATA_DIR, decisionRetentionDays(cfg.decisions?.retentionDays));
  // The admin activity log keeps its months for the same window.
  void pruneAdminActivity(DATA_DIR, decisionRetentionDays(cfg.decisions?.retentionDays));
  void pruneProblemLog(DATA_DIR);
};
pruneDecisionLog();
setInterval(pruneDecisionLog, 6 * 60 * 60_000).unref();
workspaceAccess = createWorkspaceAccess({ sessions, cookieName: SESSION_COOKIE, closeSessionStreams });
// Ten-second cadence plus the bridge's five-second backchannel deadline bounds
// stale portal access on quiet event/browser streams to fifteen seconds.
const workspaceAccessTimer = workspaceAccess ? setInterval(() => {
  void workspaceAccess!.revalidate().catch((error) => console.warn("workspace access revalidation failed", error));
}, 10_000) : null;
workspaceAccessTimer?.unref();
console.log(describeBrand(loadBrand()));

// Reclaim upload partials a previous run crashed out of, and warm the
// attachment quota cache off the same scan. This used to happen implicitly on
// every reservation, which is exactly what made uploads quadratic in
// directory size; do the initial sweep before accepting requests.
// Approval cards whose live request died with the previous process: they
// read Expired instead of staying pending forever (server/approvals/approval-restart.ts).
try {
  // Restore the durable links before startup expiry settles their sources.
  for (const { threadId, message } of openPendingInboxCards()) {
    originApprovals.observe({ type: "message.patch", threadId, message });
  }
  const closed = expireApprovalsAfterRestart({
    open: openApprovalCardMessages,
    patch: (threadId, messageId, card) => { store.patchMessage(threadId, messageId, { card }); },
    decide: ({ threadId, requestId, tool, summary }) => {
      const bot = store.botByThread(threadId);
      appendDecision(DATA_DIR, { threadId, requestId, botId: bot?.id, botName: bot?.name, tool, summary, decision: "auto-denied", source: "restart" });
    }
  });
  if (closed > 0) console.log(`[approval] expired ${closed} approval card(s) left open by the previous run`);
  // #1940: age-based expiry of every inbox kind (permission, question, request).
  const aged = runPendingApprovalExpirySweep();
  // Durable questions have no live engine after a restart. Restore their
  // attention state (iOS Needs you) without occupying a new turn's slot.
  for (const { threadId, message } of openPendingInboxCards()) {
    const bot = store.botByThread(threadId);
    if (bot && isPersistentQuestionCard(message.card) && !isApprovalCardMessage(message)) {
      store.setTaskActivity(bot.id, threadId, "waiting-on-you", { settledQuestion: true });
    }
  }
  if (aged > 0) console.log(`[approval] expired ${aged} pending approval(s) older than the configured age`);
} catch (error) {
  console.warn(`[approval] startup expiry of open approval cards failed: ${error instanceof Error ? error.message : String(error)}`);
}
setInterval(() => { runPendingApprovalExpirySweep(); }, 60 * 60_000).unref();

try {
  cleanupResumableUploads(Date.now(), recoverArchiveUpload);
  const reclaimedPartials = cleanupStaleAttachmentPartials();
  if (reclaimedPartials > 0) console.log(`reclaimed ${reclaimedPartials} abandoned upload partial(s)`);
} catch (error) {
  console.warn(`attachments: startup partial cleanup failed: ${error instanceof Error ? error.message : String(error)}`);
}
setInterval(() => { try { cleanupResumableUploads(Date.now(), recoverArchiveUpload); } catch { /* Retry the next sweep. */ } }, 60_000).unref();
videoGenerations.recover();

// #1280: retention for per-thread event logs. Off unless configured, and
// even then it only removes log files — transcripts, thread records, and
// workspace state stay untouched. A thread qualifies only when its newest
// close or archive stamp is older than the window and it is not busy,
// unread, or carrying an open direct handoff.
// #1750: never run this on the startup tick or as one synchronous walk -
// activeDirect per thread and unlinkSync across every bot blocked the
// event loop for 1-2 s while turns and SSE were already live. Defer, read
// activeDirectThreads once, and yield between batches.
const THREAD_LOG_RETENTION_SWEEP_MS = 24 * 60 * 60 * 1000;

async function sweepThreadEventLogsDeferred(): Promise<void> {
  const retentionDays = threadEventLogRetentionDays(cfg);
  if (retentionDays === null) return;
  const openDirect = coordinator.activeDirectThreads();
  const candidates: ThreadLogRetentionCandidate[] = [];
  let seen = 0;
  for (const bot of store.bots) {
    for (const task of bot.tasks ?? []) {
      candidates.push({
        threadId: task.threadId,
        closedAt: task.closedBy?.at ?? null,
        archivedAt: task.archivedAt ?? null,
        unread: task.unread === true,
        busy: threadBusy(bot.id, task.threadId),
        openDirectHandoff: openDirect.has(task.threadId)
      });
      if (++seen % 50 === 0) await new Promise<void>((resolve) => setImmediate(resolve));
    }
  }
  const swept = await sweepThreadEventLogsPaced(candidates, retentionDays);
  if (swept > 0) console.log(`[retention] removed event logs for ${swept} idle thread(s) past ${retentionDays} day(s)`);
}

function scheduleThreadEventLogRetentionSweep(): void {
  const run = () => {
    void sweepThreadEventLogsDeferred().catch((error) => {
      console.warn(`thread event log retention sweep failed: ${error instanceof Error ? error.message : String(error)}`);
    });
  };
  // After listen and the first turns: setImmediate alone can still race a
  // boot-time resume; a short delay keeps the sweep off the hot path.
  setTimeout(run, 5_000).unref();
  setInterval(run, THREAD_LOG_RETENTION_SWEEP_MS).unref();
}
scheduleThreadEventLogRetentionSweep();

// A dispatch claim is deliberately committed before transcript/provider work.
// If we died after that point, its outcome is unknown: recover the user's words
// and a review notice, never hand them to a model for a second execution.
for (const row of chatFollowups()) {
  if (row.status !== "dispatching" && row.status !== "interrupted") continue;
  const owned = row.kind === "channel"
    ? Boolean(store.groupByThread(row.threadId)?.id === row.ownerId)
    : Boolean(store.taskByThread(row.ownerId, row.threadId));
  if (!owned) { settleChatFollowups([row.id], "cancelled"); continue; }
  settleChatFollowups([row.id], "interrupted");
  const messages = store.messagesFor(row.threadId);
  const recovered = messages.find((message) => message.queueId === row.id && message.role === "user") ?? store.appendMessage(row.threadId, {
    // Aside rows recover enveloped: the words may already have run mid-turn,
    // and the recovered line must keep saying whose context it was.
    role: "user", kind: "text", text: row.kind === "aside" ? row.payload.prompt ?? row.payload.text : row.payload.text, replyToId: row.payload.replyToId,
    sendId: row.payload.sendId, queueId: row.id, sender: row.payload.sender,
    ...(row.kind === "channel" ? { channelMode: row.payload.mode, via: row.payload.via } : {}),
    ...(row.kind === "bot" ? spokenLineFields(row.payload.via, row.payload.callId) : {}),
    ...(row.kind === "aside" ? {
      aside: true,
      peerAsk: row.payload.aside
        ? { botId: row.payload.aside.fromBotId, name: row.payload.aside.fromBotName, ...(row.payload.aside.unattended ? { unattended: true } : {}) }
        : undefined
    } : {})
  });
  // Nor as a message a resumed session has not seen: count it as handed.
  const recoveredTask = row.kind !== "channel" ? store.taskByThread(row.ownerId, row.threadId) : undefined;
  const order = store.activePath(row.threadId).filter(isContextMessage).map((m) => m.id);
  for (const [instanceId, state] of Object.entries(recoveredTask?.handedMessages ?? {})) {
    if (state.session !== undefined) store.setHandedMessages(row.ownerId, row.threadId, instanceId, recordHanded(state, order, [recovered.id]));
  }
  if (!messages.some((message) => message.queueId === row.id && message.kind === "activity")) {
    store.appendMessage(row.threadId, {
      role: "bot", kind: "activity", queueId: row.id,
      tool: { name: "Queued follow-up interrupted by restart or restore — it may have already run. Review the result before sending it again.", ok: false }
    });
  }
  // The FULL-sync retirement also flushes both transcript writes. Retrying
  // this sendId now finds the canonical message, without a permanent journal scan.
  settleChatFollowups([row.id], null);
}
restoreSteeredMessages();
restoreChannelMessages();

// Auto remembers no place (2026-10-16): the auto pins an older build
// recorded are cleared before dispatch starts, on every server, whatever the
// bot's Works on. A person's pin and a legacy pin of unknown origin (it may be
// theirs) stay. The sweep is idempotent.
{
  let movedAutoPins = 0;
  for (const bot of store.bots) movedAutoPins += store.clearAutoSurfacePins(bot.id, undefined);
  if (movedAutoPins) console.log(`Auto: cleared ${movedAutoPins} auto-pinned thread(s); Auto picks where to work on each turn`);
  // Workspace is always Auto (2026-10-18): a fixed Works on and every
  // conversation pin an older build saved go back to Auto. Off stays.
  // Levels and Always allow lists stay as the person set them (#1098).
  const retired = FIXED_WORKSPACE_SEAM ? { bots: 0, pins: 0 } : store.retireFixedWorkspaces();
  if (retired.bots || retired.pins) console.log(`Workspace: ${retired.bots} bot(s) and ${retired.pins} conversation(s) back on Auto; the bot picks where each task runs`);
}
// A saved MCP server whose name is now reserved is never mounted: say so at
// start, not only at its first turn (#695 follow-up).
warnReservedMcpServers(cfg);
// Once, before any turn: the engine transcripts of threads that were
// already confidential (an older release kept them, the words from before a
// thread turned confidential included). Their next turn starts a new session
// with the thread's own transcript replayed. Then every start retries the
// purges a held database left (server/engines/engine-transcripts.ts).
{
  const done = join(DATA_DIR, ENGINE_PURGE_DONE);
  if (!existsSync(done)) {
    const keys = new Set<string>();
    const live = new Set<string>();
    let threads = 0;
    for (const bot of store.bots) {
      for (const task of store.tasks(bot.id)) {
        if (task.confidential !== true) continue;
        for (const key of threadEngineKeys(bot.id, task.threadId)) keys.add(key);
        for (const key of threadKeys(task.threadId, [join(TASK_WORKSPACES_DIR, bot.id, task.threadId)])) live.add(key);
        store.forgetEngineSessions(bot.id, task.threadId);
        threads++;
      }
    }
    try {
      purgeConfidentialEngineKeys([...keys], "already confidential", { live: [...live] });
      writeFileSync(done, "", { mode: 0o600 });
    } catch (error) {
      console.warn(`Confidential threads: could not purge their engine transcripts (${error instanceof Error ? error.message : "unknown"}); retried at the next start`);
    }
    if (threads) console.log(`Confidential threads: engine transcripts of ${threads} thread(s) purged once; their next turn starts a new session`);
  } else if (readPendingPurges(DATA_DIR).length) {
    try { purgeConfidentialEngineKeys([], "retry"); } catch { /* retried at the next start */ }
  }
}
// Organization server, once: every bot thread from before private threads
// gets its owner (server/threads/thread-privacy.ts), before anyone can read one.
migrateThreadOwners();
resetMemberAutoLevelsOnce();
// and every start after it: a level stored since (a demoted admin's bot)
settleMemberAutoLevelsFor(store.bots.map((bot) => bot.id), "at start");
hideEarlierAgentThreads();
hideBotThreadsOnce();
migrateBotRuntimeSettings();
// Unified chat (2026-11-05): background threads that finished are archived,
// the backlog first, a minute after start so nothing restarting is caught.
setTimeout(() => {
  sweepBackgroundThreads();
  setInterval(sweepBackgroundThreads, BACKGROUND_SWEEP_EVERY_MS).unref();
}, 60_000).unref();

try {
  const closedRows = closeRowsLeftByRestart(store, Date.now() - SUBAGENT_SWEEP_WINDOW_MS, Date.now());
  if (closedRows) console.log(`[startup] closed ${closedRows} call(s) and sub-agent(s) an earlier run left open`);
} catch (error) {
  console.warn(`[startup] calls left open were not closed: ${error instanceof Error ? error.message : String(error)}`);
}

const onListening = async () => {
  companyRuntimeReady();
  console.log(`openmausbot server on http://127.0.0.1:${PORT}`);
  browserSweep.start(); // what an earlier run left closes now, then once a minute
  // Words queued before the restart start first, ahead of anything sent from
  // now on. Their turns wait for the engines read at start like every turn.
  followupsReady = true;
  drainQueuedSends();
  drainQueuedChannelSends();
  // The work below wakes delegators, and a woken delegator keeps its session
  // only on an engine that records what it was handed, which that read finds
  // out: it starts once the read is done.
  if (enginesRead) {
    await enginesRead;
    if (companyShutdown) return;
  }
  settleOrphanedParallelTasks();
  // A bot left on an engine the organization no longer allows moves to Auto
  // on an allowed one before any turn starts (engines read above).
  try {
    applyOrgEngineAllowList();
  } catch (error) {
    console.warn(`[org] applying the allowed model providers failed: ${error instanceof Error ? error.message : String(error)}`);
  }
  // Startup work uses the same turn dispatcher and local tool endpoint as
  // ordinary chat. Start only once every registry is initialized and the
  // endpoint is listening; earlier dispatch can hit uninitialized bindings.
  // Cut turns resume before the scheduler's first tick, so a queued run
  // that joins the same conversation waits for the resume, not the reverse.
  resumeTurnsCutByRestart();
  // Tasks reserved for a scheduled run before a restart (pre-warm) that no
  // run took: empty and hidden, removed before schedules fire again.
  for (const bot of store.bots) {
    for (const task of bot.tasks ?? []) {
      if (task.routineRunId?.startsWith(RESERVED_RUN_PREFIX) && store.messagesFor(task.threadId).length === 0) store.deleteTask(bot.id, task.threadId);
    }
  }
  // States of watches whose routine is gone (deleted while stopped).
  try { routineWatchStates.prune(routines!.listRoutines().filter((routine) => routine.precheck?.kind === "watch").map((routine) => routine.id)); } catch { /* best effort */ }
  routines!.start();
  botWaits.start();
  headlessTasks.start();
  limitFailover.start();
  limitReset.start();
  memoryUpkeep.start();
  // Asides an older release left queued are handed to the job runtime once,
  // as one-way notices from their sender (server/peers/aside.ts).
  for (const aside of legacyPendingAsides((threadId) => store.messagesFor(threadId))) {
    const sender = store.bot(aside.fromBotId);
    if (!sender || !store.taskByThread(aside.botId, aside.threadId)) continue;
    try {
      coordinator.enqueueExternal({ botId: sender.id, threadId: sender.threadId }, { botId: aside.botId, threadId: aside.threadId }, aside.prompt, true, "notify");
    } catch (error) {
      console.error(`asides: a queued aside could not be handed on: ${error instanceof Error ? error.message : String(error)}`);
    }
  }
  importLegacyDelegations();
};
if (earlyListener) {
  earlyListener.adopt(handleRequest);
  void onListening();
} else {
  server.listen(PORT, "127.0.0.1", onListening);
}

// A second listener for `openmausbot serve --tunnel` (server/tunnel.ts): the
// connector gateway on this machine forwards public traffic to this IPC path.
// Nothing changes about the loopback bind above. Requests arriving here have
// no peer address, which request-auth treats as "through a proxy": a session
// is required, never loopback trust, whatever headers the request carries.
const TUNNEL_SOCKET = process.env.SAGAX_TUNNEL_SOCKET?.trim() || null;
let tunnelListener: ReturnType<typeof createServer> | null = null;
if (TUNNEL_SOCKET) {
  if (process.platform !== "win32") rmSync(TUNNEL_SOCKET, { force: true });
  tunnelListener = createServer(gzipTunnelReplies(handleRequest));
  desktopViewer.attach(tunnelListener, handleRequest);
  attachDesktopTunnel(tunnelListener, desktopTunnelDeps);
  attachDesktopTerminal(tunnelListener, { ...desktopTunnelDeps, terminals: desktopTerminals });
  tunnelListener.listen(TUNNEL_SOCKET, () => {
    console.log(`openmausbot tunnel listener on ${TUNNEL_SOCKET}`);
  });
}

/** Who coordinated work from this conversation acts for, so two trees of
 * the same person may share one request (runtime joins): the speaking
 * principal, or the owner of a solo server. A confidential conversation, or
 * nobody known on an organization server, never joins. */
function joinPerson(threadId: string): string | undefined {
  if (store.isConfidentialThread(threadId)) return undefined;
  const principalId = safetyPrincipal(threadId).principalId;
  if (principalId) return principalId;
  return IDENTITY.kind === "perspicax" ? undefined : "solo-owner";
}

/** The admitted request, not a later room line. This changes only the
 * approval's return address; turnOrigin still owns the work's provenance. */
function coordinationRequestId(threadId: string): string | undefined {
  return directRequestOwners.get(threadId)?.messageId ?? groupApprovalRequests.get(threadId)?.messageId;
}

/** An external runtime's idempotency key for one delegate_bot or ask_bot
 * call (body `idempotencyKey`, or the Idempotency-Key header): a retry after
 * a dropped connection sends the same key and gets the same request back.
 * Anything not shaped like a key is ignored, as if absent. */
function idempotencyKeyOf(body: Record<string, unknown>, header: string | string[] | undefined): string | undefined {
  const raw = typeof body.idempotencyKey === "string" ? body.idempotencyKey : Array.isArray(header) ? header[0] : header;
  const key = typeof raw === "string" ? raw.trim() : "";
  return /^[\w.:-]{8,128}$/.test(key) ? key : undefined;
}

/** The handoffs an older release left in delegations.json, handed to the job
 * runtime once at boot (contract §9 step 3): a one-way send as a notice, an
 * external runtime's as a poll root, any other as work whose result resumes
 * the conversation that asked (a root that waits on it). Its target and
 * route are checked again at dispatch; a review the person had not given is
 * asked then (reviewHolds). A finished routine run's handoffs are dropped,
 * as the ledger did. */
function importLegacyDelegations(): void {
  for (const item of takeLegacyDelegations()) {
    if (legacyHandoffsDropped.has(item.sourceThreadId)) continue;
    const sender = store.bot(item.sourceBotId);
    const target = store.bot(item.toBotId);
    const group = store.groupByThread(item.sourceThreadId);
    if (!sender || !target || (!group && !store.taskByThread(sender.id, item.sourceThreadId))) continue;
    // A person can reuse a finished run's task for unrelated work: only the
    // old run's handoffs are dropped, not a later request's.
    const run = routines?.runForThread(item.sourceThreadId);
    const reused = run?.finishedAt !== undefined && store.activePath(item.sourceThreadId).some((message) => message.role === "user" && message.at > run.finishedAt!);
    if (run && !["running", "waiting"].includes(run.status) && !reused) continue;
    const address = { ...(group ? { groupId: group.id } : {}), threadId: item.sourceThreadId, botId: sender.id };
    // Where the ledger would have run it: the thread opened for it, else the
    // conversation the teammate keeps for its peers.
    const threadId = item.targetThreadId && store.taskByThread(target.id, item.targetThreadId) ? item.targetThreadId : peerThreadFor(target);
    if (!threadId) continue;
    const destination = { threadId, botId: target.id };
    try {
      if (item.external || item.oneWay || group) {
        coordinator.enqueueExternal(address, destination, item.message, item.approved, item.oneWay ? "notify" : "work");
      } else {
        const generation = `legacy-${item.id || randomUUID()}`;
        coordinator.enqueue(address, generation, undefined, destination, target.id, item.message, item.approved, false, "", undefined, item.origin ?? OUTSIDE);
        coordinator.sourceSettled(generation, true);
      }
    } catch (error) {
      console.error(`delegations: a queued handoff from an older release could not be handed on: ${error instanceof Error ? error.message : String(error)}`);
    }
  }
}

/** A caller whose requests no turn of its own resumes, so the runtime gives
 * each a poll root (its results are read, not woken): an external runtime,
 * and a room turn without coordination (a room goal's member turns, which
 * their goal orchestrator runs). */
function pollOnlyCaller(capability: InternalCapability): boolean {
  return capability.generation === EXTERNAL_RUNTIME_GENERATION || (!capability.roomCoordination && Boolean(store.groupByThread(capability.threadId)));
}

/** delegate_bot on the job runtime (lot 3): the request coordinate_bots
 * makes for one teammate outside a room, answered in delegate_bot's shape.
 * Its task id is the runtime's assignment id, which check_delegation and
 * wait_delegation read back (runtimeDelegationStatus). */
async function delegateOnRuntime(from: BotRecord, target: BotRecord, message: string, capability: InternalCapability,
  delegated: (taskId: string) => void, external = false, mode: "work" | "consult" = "work", key?: string): Promise<[number, Record<string, unknown>]> {
  const room = store.groupByThread(capability.threadId);
  const address = { ...(room ? { groupId: room.id } : {}), threadId: capability.threadId, botId: from.id };
  // The teammate's name as this sender may read it at the moment it is
  // written (receiptName): `target` is the live record, which a rename
  // patches in place while a card waits, so it is never trusted for a name.
  const shownName = () => receiptName(store.bot(from.id), store.bot(target.id));
  const refused = (detail: string, status = 200): [number, Record<string, unknown>] => [status, { error: detail,
    receipt: peerDeliveryReceipt({ botId: target.id, botName: shownName(), outcome: "failed", detail: `${detail}: nothing was queued` }) }];
  if (target.id === from.id) return refused("a bot cannot delegate to itself");
  const problem = roomHandoffProblem(address) ?? roomHandoffProblem({ threadId: target.threadId, botId: target.id }, address);
  if (problem) return refused(problem, 403);
  let approvalGranted = false;
  // An external runtime's call is not held open on the card: its work waits
  // queued for the person's review (reviewHolds) and the caller polls.
  // A routine or webhook run's own delegate_bot is not held either (the
  // ledger it replaces asked once the turn ended): its run waits on the
  // work. Its ask_bot keeps asking at once, as it always did.
  const reviewLater = (external || (mode === "work" && Boolean(activeRoutineRunForThread(address.threadId)))) && peerReviewRequired(from, address.threadId);
  if (peerReviewRequired(from, address.threadId) && !reviewLater) {
    // full-access: peer-contact
    const verdict = await requestPeerApproval(approvalBus, from, target, message, "delegate_bot", address.threadId);
    if (!internalCapabilityIsActive(capability)) return refused("the turn that asked has ended", 409);
    if (verdict !== "allow") {
      const failure = peerApprovalFailure(verdict);
      return [403, { error: verdict === "deny" ? "Denied by user; no work sent." : `${failure.error}; no work sent.`, approvals: [{ botId: target.id, ...failure }] }];
    }
    // The card may have been open for minutes. Read both bots again before
    // anything touches the teammate, as ask_bot did before it moved onto the
    // runtime: one hidden, unshared or moved out of reach meanwhile gets no
    // thread and no work, and the refusal names it by the id that was
    // addressed, never by its new name (isolation between people).
    const sender = store.bot(from.id);
    const current = store.bot(target.id);
    if (!sender || !current || !canReachPeer(sender, current)) return refused("that bot is no longer available to this bot");
    approvalGranted = true;
  }
  const continued = store.workThread(target.id, from.id, address.threadId);
  const task = continued ?? store.createTask(target.id, `@${from.name} · work`, false, undefined,
    { botId: from.id, name: from.name, kind: "work", threadId: address.threadId, at: Date.now() });
  if (!task) return refused("no such bot", 404);
  if (continued) adoptReservedWorkThread(target.id, task.threadId);
  applyDelegatedLevel(from, address.threadId, store.bot(target.id)!, task.threadId);
  try {
    const sourceText = [...store.messagesFor(address.threadId)].reverse().find(m => m.role === "user" && m.kind === "text")?.text ?? "";
    const { node, duplicate } = external
      ? coordinator.enqueueExternal(address, { threadId: task.threadId, botId: target.id }, message, approvalGranted, mode, key)
      : coordinator.enqueue(address, capability.generation, capability.roomHandoffId,
        { threadId: task.threadId, botId: target.id }, target.id, message, approvalGranted, false, sourceText, undefined,
        turnOrigin(capability), mode, joinPerson(address.threadId), false, undefined, coordinationRequestId(address.threadId));
    // An external caller has no turn to end: its check reads at once.
    if (!external) delegated(node.id);
    else coordinator.tick();
    if (duplicate && !continued) store.deleteTask(target.id, task.threadId);
    else if (!continued) threadStarters.set(task.threadId, openerFrom(address.threadId));
    // A repeat answers the request already made without a fresh route check,
    // so the name is read here too, like every name this function writes.
    const shown = shownName();
    const called = shown ? `@${shown}` : "the teammate";
    if (!duplicate) store.appendMessage(address.threadId, { role: "bot", kind: "activity",
      from: { botId: from.id, name: from.name, color: from.color },
      tool: { name: `Sent to ${shown ?? "Teammate"}`, ok: true },
      threadRef: { botId: target.id, threadId: node.threadId, title: store.taskByThread(target.id, node.threadId)?.title ?? "Teammate work" } });
    return [200, { queued: true, taskId: node.id, ...(shown ? { toBotName: shown } : {}), ...(duplicate ? { duplicate: true } : {}),
      message: reviewLater ? `Queued for review: ${called} will pick it up once the user approves.`
        : external ? `Delegated: ${called} is picking it up now.` : "Queued on the job runtime: end your turn; the result resumes you automatically.",
      ...(reviewLater ? { approvalRequired: true } : {}),
      receipt: peerDeliveryReceipt({ botId: target.id, botName: shown, outcome: duplicate && node.status !== "queued" ? "injected" : "queued",
        detail: duplicate ? `already sent: it is ${node.status} and its result will resume you`
          : reviewLater ? "the teammate's turn waits on the user's approval" : "queued; it runs after your current turn ends", taskId: node.id }) }];
  } catch (error) {
    if (!continued) store.deleteTask(target.id, task.threadId);
    return refused(error instanceof Error ? error.message : String(error));
  }
}

/** check_delegation / wait_delegation for a task id delegateOnRuntime
 * returned: read from the runtime's record, in the legacy receipt's words.
 * The same ownership and access rule as a legacy receipt. */
async function runtimeDelegationStatus(taskId: string, from: BotRecord, fromThreadId: string, deadline: number): Promise<[number, Record<string, unknown>]> {
  for (;;) {
    const node = coordinator.node(taskId);
    const parent = node?.parentId ? coordinator.node(node.parentId) : undefined;
    if (!node || !parent) return [404, { error: "unknown task id" }];
    if (parent.threadId !== fromThreadId || parent.groupId) return [403, { error: "that task belongs to a different conversation" }];
    const target = store.bot(node.botId);
    const sender = store.bot(from.id);
    if (!sender || (target && !canReachPeer(sender, target))) return [403, { error: "Result withheld: team access changed while the teammate was working" }];
    const toBotName = target?.name ?? "Teammate";
    if (["completed", "failed", "cancelled"].includes(node.status)) {
      const status: DelegationReceipt["status"] = node.status === "completed" ? "done" : node.status === "cancelled" ? "cancelled" : "failed";
      return [200, { status, toBotName, result: node.result }];
    }
    // A person's card cannot advance while this caller waits. Preserve the
    // legacy poll's immediate answer for runtime work too.
    const awaitingPerson = node.status === "queued" ? undefined : openPersonCard(node.threadId);
    if (Date.now() >= deadline || awaitingPerson) {
      return [200, node.status === "queued"
        ? { status: "queued", toBotName, ...(target ? { targetStatus: peerStatus(target.activity, target.busy) } : {}) }
        : { status: "running", toBotName, elapsedMs: Math.max(0, Date.now() - (node.startedAt ?? node.createdAt)),
          recentActivity: summarizeDelegatedActivity(store.messagesFor(node.threadId), node.startedAt ?? node.createdAt),
          ...(awaitingPerson ? { awaitingPerson: {
            ...awaitingPerson,
            threadTitle: store.taskByThread(node.botId, node.threadId)?.title,
          } } : {}) }];
    }
    await new Promise(resolve => setTimeout(resolve, 500));
  }
}

/** A quit, update or restart first lets the turns in progress finish, for
 * a bounded time (SAGAX_SHUTDOWN_DRAIN_MS, server/turns/interrupted-turns.ts):
 * nothing new is dispatched meanwhile (routines paused, the coordinator
 * closed: a teammate turn that finishes keeps its result). A turn waiting
 * on a person's approval does not hold the stop. */
const SHUTDOWN_DRAIN_MS = shutdownDrainMs(process.env, Boolean(process.versions.electron));
function busyDirectThreads(): Array<{ botId: string; threadId: string }> {
  const out: Array<{ botId: string; threadId: string }> = [];
  for (const bot of store.bots) for (const task of store.tasks(bot.id)) if (threadBusy(bot.id, task.threadId)) out.push({ botId: bot.id, threadId: task.threadId });
  return out;
}
function threadWaitsOnPerson(threadId: string): boolean {
  return store.messagesFor(threadId).slice(-40).some((message) => Boolean(message.card?.requestId && !message.card.answered && !message.card.dismissed));
}
async function drainTurnsBeforeShutdown(): Promise<void> {
  // 1. Mark probes unready so the edge holds new requests (Caddy lb_try /
  //    k8s readiness) instead of answering 502 while we drain.
  markShuttingDown();
  // 2. End live SSE streams so clients reconnect with their cursor; the
  //    edge holds those reconnects until the next process is ready.
  //    #2013: each first hears that this is a planned restart (an update
  //    or a restart), so the app says "back in a moment", not "unreachable".
  //    No id: it is transport news, never a replay boundary.
  const restarting = `data: ${JSON.stringify({ kind: "server.restarting", at: Date.now() })}\n\n`;
  // A copy on purpose: close() removes the client from the live set.
  // oxlint-disable-next-line unicorn/no-useless-spread
  for (const client of [...sseClients]) {
    try { deliverSseFrame(client, "server.restarting", restarting); } catch { /* already gone */ }
    try { client.close(); } catch { /* already gone */ }
  }
  routines?.pause();
  coordinator.close();
  // Written first, so a stop that kills the process during the drain (a
  // short container grace period) still resumes them; rewritten after.
  noteTurnsCutByShutdown(false);
  const left = await drainTurns({ busy: () => busyDirectThreads().map((t) => t.threadId), waitingOnPerson: threadWaitsOnPerson, timeoutMs: SHUTDOWN_DRAIN_MS });
  console.log(`shutdown: ${left.length ? `${left.length} turn(s) still working, resumed at the next start` : "no turn in progress"}`);
  // 3. Stop accepting and finish in-flight HTTP within the remaining budget.
  //    Runtime state is already durable; bus/session flush runs in exit().
  const httpBudget = Math.max(1_000, Math.min(SHUTDOWN_DRAIN_MS || 5_000, 10_000));
  await drainHttpServers([server, webhookIngress?.server, tunnelListener], { timeoutMs: httpBudget });
}

/** The turns the drain did not see finish are cut, and no turn.completed
 * reaches those threads. Each says so now, instead of leaving a message
 * unanswered with no reason; the line is all it adds (no unread, no push).
 * A direct turn is written down and resumes once at the next start
 * (resumeTurnsCutByRestart); a routine run resumes through its own record
 * (RoutineManager.takeRestartResumes); a hand-off turn the next start goes
 * on with (the runtime's restart policy) is left to say so then. */
function noteTurnsCutByShutdown(final = true): void {
  const cut: InterruptedTurn[] = [];
  for (const { botId, threadId } of busyDirectThreads()) {
    if (coordinator.continuesAfterRestart(threadId)) continue;
    // A turn held on an approval card is not resumed: the card cannot answer
    // the engine that asked; it ends here with the cut line, as before.
    const held = threadWaitsOnPerson(threadId);
    if (routines?.isActiveThread(threadId) || held) {
      if (final) store.appendMessage(threadId, { role: "bot", kind: "activity", tool: held ? failedTurnTool("turn interrupted — Sagax restarted")
        : { name: "Sagax restarted during this run; it resumes when Sagax is back", ok: true } });
      continue;
    }
    const speaker = turnSpeakers.get(threadId);
    cut.push({ botId, threadId, at: Date.now(), ...(speaker ? { speaker: { ...speaker } } : {}) });
    if (final) store.appendMessage(threadId, { role: "bot", kind: "activity", tool: { name: "Sagax restarted during this turn; it resumes when Sagax is back", ok: true } });
  }
  try {
    saveInterruptedTurns(DATA_DIR, cut);
  } catch (error) {
    console.error(`shutdown: the cut turns could not be written down: ${error instanceof Error ? error.message : String(error)}`);
  }
}

/** At start: each routine run and direct turn the last stop cut goes on once
 * in its own conversation, told to check what was already done first. */
function resumeTurnsCutByRestart(): void {
  // Pre-at-rest held journal (DATA_DIR/held-steers.json) → per-thread sealed files.
  try { migrateLegacyHeldSteers(DATA_DIR); }
  catch (error) { console.warn(`held-steers: legacy migrate failed: ${error instanceof Error ? error.message : String(error)}`); }
  for (const run of routines?.takeRestartResumes() ?? []) {
    const threadId = run.threadId!;
    if (!store.taskByThread(run.botId, threadId)) { routines?.failRunById(run.id, ROUTINE_RESTARTED); continue; }
    // Its teammate work goes on under the runtime's restart policy, which
    // resumes this thread itself: no second resume here.
    if (coordinator.continuesAfterRestart(threadId)) continue;
    // The resumed turn decides again: handoffs the cut turn left queued (an
    // older release's queue) would start work it may no longer want.
    legacyHandoffsDropped.add(threadId);
    store.appendMessage(threadId, { role: "bot", kind: "activity", tool: { name: "Resuming after a restart", ok: true } });
    void startTurn(run.botId, ROUTINE_RESUME_PROMPT, { threadId, cardContinuation: true })
      .catch((error) => routines?.failRunById(run.id, `${ROUTINE_RESTARTED}: ${error instanceof Error ? error.message : String(error)}`));
  }
  let cut: ReturnType<typeof takeInterruptedTurns>;
  try {
    cut = takeInterruptedTurns(DATA_DIR);
  } catch (error) {
    console.error(`startup: the turns cut by the last stop could not be read: ${error instanceof Error ? error.message : String(error)}`);
    return;
  }
  const failed = (threadId: string, why: string) =>
    store.appendMessage(threadId, { role: "bot", kind: "activity", tool: failedTurnTool(why) });
  for (const turn of cut.stale) if (store.taskByThread(turn.botId, turn.threadId)) failed(turn.threadId, "turn interrupted — Sagax restarted");
  const resumedThreads = new Set<string>();
  for (const turn of cut.resume) {
    if (!store.taskByThread(turn.botId, turn.threadId) || threadBusy(turn.botId, turn.threadId)) continue;
    store.appendMessage(turn.threadId, { role: "bot", kind: "activity", tool: { name: "Resuming after a restart", ok: true } });
    // Messages accepted into the cut turn stay answered once: fold them into
    // this resume (D2), then drop the durable rows so crash recovery does not
    // start a second follow-up for the same words.
    let held: ReturnType<typeof takeHeldSteersForThread> = [];
    try { held = takeHeldSteersForThread(DATA_DIR, turn.threadId); }
    catch (error) { console.warn(`held-steers: could not take for resume: ${error instanceof Error ? error.message : String(error)}`); }
    const prompt = resumePromptWithHeld(TURN_RESUME_PROMPT, held);
    resumedThreads.add(turn.threadId);
    void startTurn(turn.botId, prompt, {
      threadId: turn.threadId, cardContinuation: true,
      ...(turn.speaker ? { speaker: turn.speaker as TurnSpeaker } : {})
    }).catch((error) => failed(turn.threadId, `turn interrupted — Sagax restarted; resuming failed: ${error instanceof Error ? error.message : String(error)}`));
  }
  // Crash path (no interrupted-turns.json): held rows that no resume took
  // become one follow-up turn per thread, like busy lines draining together.
  resumeHeldSteersAfterCrash(resumedThreads);
}

/** After a crash cut the turn with no resume record: run each thread's held
 * steered messages once as one follow-up (D1). Skips threads a graceful
 * resume already answered. */
function resumeHeldSteersAfterCrash(alreadyResumed: ReadonlySet<string>): void {
  let remaining: Map<string, ReturnType<typeof takeHeldSteersForThread>>;
  try { remaining = takeRemainingHeldSteers(DATA_DIR); }
  catch (error) {
    console.warn(`held-steers: could not take remaining after crash: ${error instanceof Error ? error.message : String(error)}`);
    return;
  }
  for (const [threadId, held] of remaining) {
    if (alreadyResumed.has(threadId) || held.length === 0) continue;
    const botId = held[0]!.botId;
    if (!store.taskByThread(botId, threadId) || threadBusy(botId, threadId)) continue;
    // The steered rows must still be in the transcript; otherwise a corrupt
    // journal would invent a follow-up for words nobody sent.
    const path = store.activePath(threadId);
    if (!held.every((row) => path.some((message) => message.id === row.messageId))) continue;
    const prompt = joinHeldSteerTexts(held);
    if (!prompt.trim()) continue;
    store.appendMessage(threadId, { role: "bot", kind: "activity", tool: { name: "Continuing messages sent before the restart", ok: true } });
    // cardContinuation: the held rows are already in the transcript; this turn
    // answers them once without appending another user line (same shape as a
    // cut-turn resume that carries held words).
    void startTurn(botId, prompt, {
      threadId,
      cardContinuation: true,
      excludeMessageIds: held.map((row) => row.messageId)
    }).catch((error) => {
      if (!store.taskByThread(botId, threadId)) return;
      store.appendMessage(threadId, {
        role: "bot", kind: "activity",
        tool: failedTurnTool(`messages sent before the restart could not continue: ${error instanceof Error ? error.message : String(error)}`)
      });
    });
  }
}

const gracefulShutdown = createGracefulShutdown({
  drain: drainTurnsBeforeShutdown,
  drainTimeoutMs: SHUTDOWN_DRAIN_MS + 1_000,
  cleanup: [
    () => {
      followupsReady = false;
      companyShutdown = true;
      // Before any provider is torn down: what the teardown fails stays cut
      // for the next start, and the conversations it cuts say so now.
      coordinator.close();
      noteTurnsCutByShutdown();
      if (workspaceAccessTimer) clearInterval(workspaceAccessTimer);
      // Child MCP processes and the HTTP listener can remain alive while the
      // asynchronous shutdown jobs drain. Invalidate their turn bearers before
      // any cleanup function reaches an await.
      revokeAllInternalCapabilities();
      sharedComputers.close();
      void widgetRenderer.close();
      desktopBridges.close();
      desktopTerminals.close();
      terminalFeature.sessions.stop();
      desktopLocalModels.close();
      desktopTunnels.close();
      void egressProxy?.close();
      sharedComputerControl.close();
      browserLive.closeAll();
      browserNetworkDebug.clearAll();
      desktopViewer.closeAll();
      for (const idle of localVmIdles.values()) idle.cancel();
      vps.closeAllVpsDesktopTunnels();
      watchdog.stop();
      perspicaxReach?.stop();
      botWaits.stop();
      routines?.stop();
      headlessTasks.stop();
      calendarCalls?.stop();
      memoryUpkeep.stop();
      limitReset.stop();
      cacheKeepWarm.dispose();
      webhookIngress?.server.close();
      tunnelListener?.close();
    },
    async () => { await videoGenerations.close(); await managedDesktop.close(); await registry.disposeAll(); },
    // Every open DuckDB database flushes and closes; the next start reopens them.
    async () => { await dataEngine.closeAll().catch((error) => console.warn("data: close failed", error)); },
    async () => {
      // A temporary browser's own close and the sweep's close of the same
      // browser are one close (closeBrowserSession joins them).
      const temporaries = [...temporaryBrowserSessions.keys()].map((botId) => forgetTemporaryBrowser(botId));
      meetingService.leaveAll();
      await Promise.all([...temporaries, browserSweep.closeAll(), myChrome.close().catch(() => undefined)]);
      await browserRuntime.closeAll();
    },
    // Slice 5: the Perspicax MCP tokens revoked above, bounded.
    async () => { await settledWithin(perspicaxEnding, 3_000); },
    () => liveCalls.shutdown(),
    () => flushAllProfileHistory(),
    () => flushAllMemoryJournals(),
    () => flushUsageLedger(DATA_DIR),
    () => flushDecisionLog(DATA_DIR),
    () => flushAdminActivity(DATA_DIR),
    () => runtimeDeltaCoalescer.flushAll(),
    () => bus.flush(),
    () => closeMessageSearch(),
  ],
  // Cleanup jobs run concurrently. Release only after they settle (or reach
  // the shutdown deadline), immediately before the process exits, so no new
  // server can overlap with a still-mutating old one.
  exit: (code) => {
    let finished = false;
    const finish = (exitCode: number) => {
      if (finished) return;
      finished = true;
      try { sessions.close(); }
      catch {
        // An uncleared marker makes saved account sessions require sign-in on
        // the next boot; never label failed persistence a clean shutdown.
        console.error("Session persistence failed during shutdown; account sign-in will be required again.");
        exitCode = 1;
      }
      semanticIndex.stop();
      closeMessageDb();
      releaseDataDirLeaseAtExit();
      process.exit(exitCode);
    };
    // Streamed text still merging, and any canonical lines queued after the
    // cleanup flush, reach disk before exit. A stuck append cannot hold the
    // process: the cleanup deadline already elapsed, so this wait is short.
    void bus.flushWithin(1_000).then((done) => {
      if (!done) console.error("bus: the canonical event log did not finish writing at exit; the newest thread history may be incomplete.");
      finish(code);
    }, (error: unknown) => {
      console.error("bus: canonical event log flush failed; the newest thread history may be incomplete.", error);
      finish(code);
    });
  }
});

for (const signal of ["SIGINT", "SIGTERM"] as const) {
  process.on(signal, gracefulShutdown);
}
